{"path":"/workspace/native/src/main.rs","command":"create","file_text":"mod args;
mod colors;
mod files;
mod ignore;
mod paths;
mod runner;
mod version;

use std::io::{self, Read, Write};
use std::process;

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args::parse(&args) {
        Ok((options, positional)) => {
            if positional.is_empty() && !options.stdin {
                let mut msg = String::from(
                    "Error: You have to provide at least one file/directory to transform.\n\n---\n\n",
                );
                msg.push_str(&args::help_text());
                let _ = io::stderr().write_all(msg.as_bytes());
                process::exit(1);
            }

            let paths = if options.stdin {
                let mut buffer = String::new();
                let _ = io::stdin().read_to_string(&mut buffer);
                buffer.split('\n').map(|s| s.to_string()).collect()
            } else {
                positional
            };

            if let Err(err) = runner::run(options, paths) {
                let _ = writeln!(io::stderr(), "{err}");
                process::exit(1);
            }
        }
        Err(err) => {
            let stream: &mut dyn Write = if err.exit_code == 0 {
                &mut io::stdout()
            } else {
                &mut io::stderr()
            };
            let _ = stream.write_all(err.message.as_bytes());
            process::exit(err.exit_code);
        }
    }
}
"}

