pub fn default_extensions() -> String {
    // Matches @babel/core DEFAULT_EXTENSIONS plus ts/tsx, stripped of dots, sorted.
    let mut exts = vec!["js", "jsx", "es6", "es", "mjs", "cjs", "ts", "tsx"];
    exts.sort_unstable();
    exts.join(",")
}

fn format_option(option: &OptDef) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = option.abbr {
        text.push('-');
        text.push_str(abbr);
        text.push_str(", ");
    } else {
        text.push_str("    ");
    }
    text.push_str("--");
    if option.flag {
        text.push_str("(no-)");
    }
    text.push_str(option.full);
    if let Some(choices) = option.choices {
        text.push('=');
        text.push_str(&choices.join("|"));
    } else if let Some(metavar) = option.metavar {
        text.push('=');
        text.push_str(metavar);
    }
    if option.list {
        text.push_str(" ...");
    }
    if option.default_help.is_some() || option.default_display.is_some() || option.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len()));
        }
        let text_length = text.len();
        if let Some(help) = option.help {
            text.push_str(help);
        }
        if option.default_help.is_some() || option.default_display.is_some() {
            if option.help.is_some() {
                text.push('\n');
            }
            text.push_str(&" ".repeat(text_length));
            text.push_str("(default: ");
            if let Some(h) = option.default_help {
                text.push_str(h);
            } else if let Some(d) = &option.default_display {
                text.push_str(d);
            }
            text.push(')');
        }
    }
    text
}

pub fn help_text() -> String {
    let mut opts = defs();
    opts.sort_by_key(|o| o.display_index);
    let formatted: Vec<String> = opts.iter().map(format_option).collect();
    format!(
        "Usage: jscodeshift [OPTION]... PATH...\n  \
         or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  \
         or:  jscodeshift [OPTION]... -t URL PATH...\n  \
         or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\n\
         Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.\n\
         If --stdin is set, each line of the standard input is used as a path.\n\n\
         Options:\n\
         \"...\" behind an option means that it can be supplied multiple times.\n\
         All options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n\
         {}\n",
        formatted.join("\n")
    )
}

fn throw_error(exit_code: i32, message: String, with_help: bool) -> ParseError {
    let message = if with_help {
        format!("{message}\n\n---\n\n{}", help_text())
    } else {
        message
    };
    ParseError { exit_code, message }
}

fn is_option(value: &str) -> bool {
    value.starts_with('-') && value != "-"
}

fn strip_option_prefix(name: &str) -> String {
    let rest = if let Some(s) = name.strip_prefix("--") {
        s
    } else if let Some(s) = name.strip_prefix('-') {
        s
    } else {
        name
    };
    rest.strip_prefix("no-").unwrap_or(rest).to_string()
}

fn process_unknown(value: &str) -> Value {
    match serde_json::from_str::<Value>(value) {
        Ok(v) => v,
        Err(_) => Value::String(value.to_string()),
    }
}

fn js_number(value: &str) -> Value {
    // Number(value) in JS
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return Value::Number(0.into());
    }
    match trimmed.parse::<f64>() {
        Ok(n) if n.is_finite() => json_number(n),
        Ok(_) => Value::Null,
        Err(_) => Value::Null,
    }
}

struct Prepared {
    by_flag: BTreeMap<String, OptDef>,
}

fn prepare() -> Prepared {
    let mut by_flag = BTreeMap::new();
    for option in defs() {
        by_flag.insert(format!("--{}", option.full), option.clone());
        if let Some(abbr) = option.abbr {
            by_flag.insert(format!("-{abbr}"), option.clone());
        }
        if option.flag {
            by_flag.insert(format!("--no-{}", option.full), option.clone());
        }
    }
    Prepared { by_flag }
}

pub fn parse(args: &[String]) -> Result<(Options, Vec<String>), ParseError> {
    let prepared = prepare();
    let mut extra: BTreeMap<String, Value> = BTreeMap::new();
    let mut extra_is_list: BTreeMap<String, bool> = BTreeMap::new();

    let mut transform = "./transform.js".to_string();
    let mut cpus: Option<f64> = None;
    let mut verbose: Value = Value::from(0);
    let mut dry = false;
    let mut print = false;
    let mut babel = true;
    let mut extensions = default_extensions();
    let mut ignore_pattern: Vec<String> = Vec::new();
    let mut ignore_config: Vec<String> = Vec::new();
    let mut gitignore = false;
    let mut run_in_band = false;
    let mut silent = false;
    let mut parser = "babel".to_string();
    let mut parser_config: Option<Value> = None;
    let mut fail_on_error = false;
    let mut stdin = false;
    let mut missing: Vec<String> = Vec::new();

    let mut positional: Vec<String> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let (option_name, inline_value) = if let Some(idx) = arg.find('=') {
                (arg[..idx].to_string(), Some(arg[idx + 1..].to_string()))
            } else {
                (arg.clone(), None)
            };

            if option_name == "--help" || option_name == "-h" {
                return Err(throw_error(0, help_text(), false));
            }
            if option_name == "--version" {
                return Err(throw_error(0, version::version_text(), false));
            }

            if let Some(option) = prepared.by_flag.get(&option_name) {
                if option.flag {
                    let value = if option_name.starts_with("--no-") {
                        false
                    } else if let Some(v) = &inline_value {
                        v == "1"
                    } else {
                        true
                    };
                    match option.key {
                        "dry" => dry = value,
                        "print" => print = value,
                        "babel" => babel = value,
                        "gitignore" => gitignore = value,
                        "runInBand" => run_in_band = value,
                        "silent" => silent = value,
                        "failOnError" => fail_on_error = value,
                        "stdin" => stdin = value,
                        _ => {}
                    }
                } else {
                    let mut value = inline_value.clone();
                    if value.is_none() && i + 1 < args.len() && !is_option(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 1;
                    }
                    if let Some(v) = value {
                        match option.key {
                            "transform" => transform = v,
                            "cpus" => {
                                cpus = match v.trim().parse::<f64>() {
                                    Ok(n) if n.is_finite() => Some(n),
                                    _ => Some(f64::NAN),
                                };
                            }
                            "verbose" => verbose = js_number(&v),
                            "extensions" => extensions = v,
                            "ignorePattern" => ignore_pattern.push(v),
                            "ignoreConfig" => ignore_config.push(v),
                            "parser" => parser = v,
                            "parserConfig" => {
                                let contents = fs::read_to_string(&v).map_err(|e| ParseError {
                                    exit_code: 1,
                                    message: e.to_string(),
                                })?;
                                let parsed: Value =
                                    serde_json::from_str(&contents).map_err(|e| ParseError {
                                        exit_code: 1,
                                        message: e.to_string(),
                                    })?;
                                parser_config = Some(parsed);
                            }
                            _ => {}
                        }
                    } else {
                        missing.push(option.full.to_string());
                    }
                }
            } else {
                // Unknown options are passed along, matching the JS parser.
                let real_option_name = strip_option_prefix(&option_name);
                let already = extra.contains_key(&real_option_name);
                let prev_is_true = extra.get(&real_option_name) == Some(&Value::Bool(true));
                let is_list = already && !prev_is_true;
                extra_is_list.insert(real_option_name.clone(), is_list);

                let looks_like_flag = !already
                    && inline_value.is_none()
                    && (i + 1 >= args.len() || is_option(&args[i + 1]));

                if looks_like_flag {
                    let value = if option_name.starts_with("--no-") {
                        Value::Bool(false)
                    } else {
                        Value::Bool(true)
                    };
                    extra.insert(real_option_name, value);
                } else {
                    let mut value = inline_value.clone();
                    if value.is_none() && i + 1 < args.len() && !is_option(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 1;
                    }
                    if let Some(v) = value {
                        let processed = process_unknown(&v);
                        if is_list {
                            match extra.get_mut(&real_option_name) {
                                Some(Value::Array(arr)) => arr.push(processed),
                                Some(prev) => {
                                    let old = prev.clone();
                                    if old == Value::Bool(true) {
                                        extra.insert(
                                            real_option_name,
                                            Value::Array(vec![processed]),
                                        );
                                    } else {
                                        extra.insert(
                                            real_option_name,
                                            Value::Array(vec![old, processed]),
                                        );
                                    }
                                }
                                None => {
                                    extra.insert(real_option_name, Value::Array(vec![processed]));
                                }
                            }
                        } else if already {
                            match extra.get_mut(&real_option_name) {
                                Some(Value::Array(arr)) => arr.push(processed),
                                Some(prev) => {
                                    let old = prev.clone();
                                    extra.insert(
                                        real_option_name,
                                        Value::Array(vec![old, processed]),
                                    );
                                }
                                None => {
                                    extra.insert(real_option_name, processed);
                                }
                            }
                        } else {
                            extra.insert(real_option_name, processed);
                        }
                    } else {
                        extra.insert(real_option_name, Value::String(MISSING.into()));
                    }
                }
            }
        } else if arg.chars().all(|c| c.is_ascii_digit()) && !arg.is_empty() {
            positional.push(arg.clone());
            // JS converts /^\d+$/ to Number; we keep the string form for paths,
            // but numeric-looking positional args are still valid path strings.
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }

    if !missing.is_empty() {
        return Err(throw_error(
            1,
            format!("Missing value: --{} requires a value", missing[0]),
            true,
        ));
    }

    // Validate choices
    let mut errors = Vec::new();
    let verbose_ok = matches!(verbose, Value::Number(ref n) if n.as_i64() == Some(0) || n.as_i64() == Some(1) || n.as_i64() == Some(2));
    if !verbose_ok {
        errors.push("Error: --verbose must be one of the values 0,1,2".to_string());
    }
    let allowed_parsers = ["babel", "babylon", "flow", "ts", "tsx"];
    if !allowed_parsers.contains(&parser.as_str()) {
        errors.push(
            "Error: --parser must be one of the values babel,babylon,flow,ts,tsx".to_string(),
        );
    }
    if !errors.is_empty() {
        return Err(throw_error(1, errors.join("\n"), true));
    }

    let verbose_i = verbose.as_i64().unwrap_or(0) as i32;

    let _ = extra_is_list;
    let _ = Path::new(".");

    Ok((
        Options {
            transform,
            cpus,
            verbose: verbose_i,
            dry,
            print,
            babel,
            extensions,
            ignore_pattern,
            ignore_config,
            gitignore,
            run_in_band,
            silent,
            parser,
            parser_config,
            fail_on_error,
            stdin,
            extra,
        },
        positional,
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn help_starts_with_usage() {
        let h = help_text();
        assert!(h.starts_with("Usage: jscodeshift"));
        assert!(h.contains("--(no-)babel"));
        assert!(h.contains("--ignore-pattern=GLOB ..."));
    }
}
"}

{"path":"/workspace/native/src/colors.rs","command":"create","file_text":"//! picocolors-compatible color helpers.
use std::env;
use std::io::{self, IsTerminal};

fn argv_has(flag: &str) -> bool {
    env::args().any(|a| a == flag)
}

pub fn is_color_supported() -> bool {
    let no_color = env::var_os("NO_COLOR").is_some() || argv_has("--no-color");
    if no_color {
        return false;
    }
    if env::var_os("FORCE_COLOR").is_some() || argv_has("--color") {
        return true;
    }
    if cfg!(windows) {
        return true;
    }
    if env::var_os("CI").is_some() {
        return true;
    }
    let term_dumb = env::var("TERM").map(|t| t == "dumb").unwrap_or(false);
    io::stdout().is_terminal() && !term_dumb
}

fn wrap(open: &str, close: &str, s: &str) -> String {
    if is_color_supported() {
        format!("{open}{s}{close}")
    } else {
        s.to_string()
    }
}

pub fn red(s: &str) -> String {
    wrap("\u{1b}[31m", "\u{1b}[39m", s)
}
pub fn green(s: &str) -> String {
