{"path":"/workspace/native/src/ignore.rs","command":"create","file_text":"use globset::{GlobBuilder, GlobSet, GlobSetBuilder};
use std::fs;
use std::io::{self, ErrorKind};
use std::path::Path;

/// Gitignore-style ignore matching, matching jscodeshift's ignoreFiles.js.
#[derive(Default)]
pub struct Ignores {
    patterns: Vec<String>,
}

impl Ignores {
    pub fn new() -> Self {
        Self {
            patterns: Vec::new(),
        }
    }

    pub fn add<I, S>(&mut self, input: I)
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        for item in input {
            self.add_pattern(item.as_ref());
        }
    }

    pub fn add_from_file(&mut self, path: &Path) -> io::Result<()> {
        let meta = match fs::metadata(path) {
            Ok(m) => m,
            Err(e) if e.kind() == ErrorKind::NotFound => return Err(e),
            Err(e) => return Err(e),
        };
        if meta.is_file() {
            let content = fs::read_to_string(path)?;
            for line in content.split('\n') {
                let line = line.strip_suffix('\r').unwrap_or(line);
                self.add_pattern(line);
            }
        }
        Ok(())
    }

    pub fn add_from_files(&mut self, files: &[String]) -> io::Result<()> {
        for f in files {
            self.add_from_file(Path::new(f))?;
        }
        Ok(())
    }

    fn add_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let pattern = val.to_string();
        if !pattern.contains('/') {
            self.patterns.push(format!("**/{pattern}"));
        } else if pattern.ends_with('/') {
            self.patterns.push(format!("**/{pattern}**"));
            self.patterns.push(format!("{pattern}**"));
        }
        self.patterns.push(pattern);
    }

    pub fn is_empty(&self) -> bool {
        self.patterns.is_empty()
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        if self.patterns.is_empty() {
            return false;
        }
        if matches_any(&self.patterns, path) {
            return true;
        }
        let normalized = strip_traversal_prefix(path);
        if normalized != path {
            return matches_any(&self.patterns, normalized);
        }
        false
    }
}

fn strip_traversal_prefix(path: &str) -> &str {
    let mut rest = path;
    loop {
        if let Some(s) = rest.strip_prefix("../") {
            rest = s;
            continue;
        }
        if let Some(s) = rest.strip_prefix("..\\") {
            rest = s;
            continue;
        }
        if let Some(s) = rest.strip_prefix("./") {
            rest = s;
            continue;
        }
        if let Some(s) = rest.strip_prefix(".\\") {
            rest = s;
            continue;
        }
        break;
    }
    rest
}

fn matches_any(patterns: &[String], path: &str) -> bool {
    let mut builder = GlobSetBuilder::new();
    let mut any = false;
    for p in patterns {
        if let Ok(glob) = GlobBuilder::new(p)
            .literal_separator(true)
            .backslash_escape(false)
            .build()
        {
            builder.add(glob);
            any = true;
        }
    }
    if !any {
        return false;
    }
    match builder.build() {
        Ok(set) => set_matches(&set, path),
        Err(_) => false,
    }
}

fn set_matches(set: &GlobSet, path: &str) -> bool {
    // picomatch {dot:true} matches hidden files; globset does this by default
    // unless we set require_literal_separator. Also try basename match like picomatch.
    if set.is_match(path) {
        return true;
    }
    if let Some(name) = Path::new(path).file_name().and_then(|s| s.to_str()) {
        if set.is_match(name) {
            return true;
        }
    }
    false
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ignores_node_modules() {
        let mut ig = Ignores::new();
        ig.add(["node_modules"]);
        assert!(ig.should_ignore("foo/node_modules/bar.js"));
        assert!(ig.should_ignore("node_modules/bar.js"));
        assert!(!ig.should_ignore("src/app.js"));
    }

    #[test]
    fn strips_traversal() {
        let mut ig = Ignores::new();
        ig.add(["**/node_modules/**"]);
        assert!(ig.should_ignore("../src/node_modules/x.js"));
        assert!(ig.should_ignore("./node_modules/x.js"));
    }
}
"}

{"path":"/workspace/native/src/files.rs","command":"create","file_text":"use crate::ignore::Ignores;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};

/// Recursively collect files matching `filter`, honoring ignore rules.
/// Mirrors Runner.js getAllFiles / dirFiles.
pub fn get_all_files(
    paths: &[String],
    extensions: Option<&[String]>,
    ignores: &Ignores,
) -> io::Result<Vec<String>> {
    let mut out = Vec::new();
    for file in paths {
        if file.is_empty() {
            // stdin split produces a trailing empty line; lstat fails
            let _ = io::stderr().write_all(format!("Skipping path {file} which does not exist. \n").as_bytes());
            continue;
        }
        match fs::symlink_metadata(file) {
            Err(_) => {
                let _ = io::stderr()
                    .write_all(format!("Skipping path {file} which does not exist. \n").as_bytes());
            }
            Ok(stat) => {
                if stat.is_dir() {
                    let mut acc = Vec::new();
                    dir_files(Path::new(file), ignores, &mut acc)?;
                    for name in acc {
                        if matches_ext(&name, extensions) {
                            out.push(name);
                        }
                    }
                } else if !matches_ext(file, extensions) || ignores.should_ignore(file) {
                    // ignoring the file
                } else {
                    out.push(file.clone());
                }
            }
        }
    }
    Ok(out)
}

fn matches_ext(name: &str, extensions: Option<&[String]>) -> bool {
    match extensions {
        None => true,
        Some(exts) => {
            let ext = Path::new(name)
                .extension()
                .and_then(|s| s.to_str())
                .map(|s| format!(".{s}"))
                .unwrap_or_default();
            exts.iter().any(|e| e == &ext)
        }
    }
}

fn dir_files(dir: &Path, ignores: &Ignores, acc: &mut Vec<String>) -> io::Result<()> {
    // JS joins with trailing slash for recursion; path semantics are the same.
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(e) => return Err(e),
    };
    // Collect then sort? JS uses readdir order (unspecified). Keep filesystem order.
    let mut names: Vec<PathBuf> = Vec::new();
    for entry in entries {
        let entry = entry?;
        names.push(entry.path());
    }
    for name in names {
        let name_str = name.to_string_lossy().to_string();
        match fs::metadata(&name) {
            Err(_) => {
                let _ = io::stdout().write_all(
                    format!("Skipping path \"{name_str}\" which does not exist.\n").as_bytes(),
                );
            }
            Ok(stats) => {
                if ignores.should_ignore(&name_str) {
                    continue;
                } else if stats.is_dir() {
                    dir_files(&name, ignores, acc)?;
                } else {
                    acc.push(name_str);
                }
            }
        }
    }
    Ok(())
}
"}

{"path":"/workspace/native/src/paths.rs","command":"create","file_text":"use std::env;
use std::path::{Path, PathBuf};

/// Resolve the directory that contains this binary / package root.
pub fn package_root() -> PathBuf {
    if let Ok(root) = env::var("JSCODESHIFT_ROOT") {
        return PathBuf::from(root);
    }
    if let Ok(exe) = env::current_exe() {
        // Typical layouts:
        //   <root>/target/release/jscodeshift
        //   <root>/target/debug/jscodeshift
        //   <root>/bin/jscodeshift
        if let Some(dir) = exe.parent() {
            if dir.ends_with("release") || dir.ends_with("debug") {
                if let Some(target) = dir.parent() {
                    if target.ends_with("target") {
                        if let Some(root) = target.parent() {
                            return root.to_path_buf();
                        }
                    }
                }
            }
            if dir.ends_with("bin") {
                if let Some(root) = dir.parent() {
                    return root.to_path_buf();
                }
            }
            return dir.to_path_buf();
        }
    }
    env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

pub fn transform_host() -> PathBuf {
    package_root().join("bridge").join("transform-host.js")
}

pub fn node_binary() -> PathBuf {
    if let Ok(node) = env::var("NODE") {
        return PathBuf::from(node);
    }
    PathBuf::from("node")
}

pub fn resolve_transform(transform: &str) -> String {
    if transform.starts_with("http://") || transform.starts_with("https://") {
        return transform.to_string();
    }
    let p = Path::new(transform);
    if p.is_absolute() {
        transform.to_string()
    } else {
        env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(p)
            .to_string_lossy()
            .to_string()
    }
}
"}

{"path":"/workspace/native/src/version.rs","command":"create","file_text":"use crate::paths;
use serde_json::Value;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

/// Print version information matching bin/jscodeshift.js --version.
pub fn version_text() -> String {
    let root = paths::package_root();
    let pkg_version = read_pkg_version(&root.join("package.json")).unwrap_or_else(|| "17.4.0".into());
    let babel = node_pkg_version(&root, "@babel/core").unwrap_or_else(|| "?".into());
    let babylon = require_package(&root, "@babel/parser").unwrap_or_else(|| "?".into());
    let flow = require_package(&root, "flow-parser").unwrap_or_else(|| "?".into());
    let recast = require_package(&root, "recast").unwrap_or_else(|| "?".into());
    format!(
        "jscodeshift: {pkg_version}\n - babel: {babel}\n - babylon: {babylon}\n - flow: {flow}\n - recast: {recast}\n"
    )
}

fn read_pkg_version(path: &Path) -> Option<String> {
    let text = fs::read_to_string(path).ok()?;
    let v: Value = serde_json::from_str(&text).ok()?;
    v.get("version")?.as_str().map(|s| s.to_string())
}

fn node_pkg_version(root: &Path, name: &str) -> Option<String> {
    // Prefer require('<name>/package.json').version via node to match JS exactly.
    let script = format!(
        "try {{ process.stdout.write(require({name:?}).version || ''); }} catch (e) {{ process.exit(2); }}"
    );
    let out = Command::new(paths::node_binary())
        .arg("-e")
        .arg(script)
        .current_dir(root)
        .output()
        .ok()?;
    if out.status.success() {
        let s = String::from_utf8_lossy(&out.stdout).to_string();
        if !s.is_empty() {
            return Some(s);
        }
    }
    None
}

/// Walk from require.resolve(name) up looking for package.json with matching name.
fn require_package(root: &Path, name: &str) -> Option<String> {
    let script = format!(
        "try {{ process.stdout.write(require.resolve({name:?})); }} catch (e) {{ process.exit(2); }}"
    );
    let out = Command::new(paths::node_binary())
        .arg("-e")
        .arg(script)
        .current_dir(root)
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let entry = String::from_utf8_lossy(&out.stdout).to_string();
    let mut dir = PathBuf::from(entry);
    if dir.is_file() {
        dir.pop();
    }
    loop {
        let pkg = dir.join("package.json");
        if let Ok(text) = fs::read_to_string(&pkg) {
            if let Ok(v) = serde_json::from_str::<Value>(&text) {
                if v.get("name").and_then(|n| n.as_str()) == Some(name) {
                    return v.get("version").and_then(|x| x.as_str()).map(|s| s.to_string());
                }
            }
        }
        if !dir.pop() {
            break;
        }
        if dir.as_os_str().is_empty() || dir == Path::new("/") {
            break;
        }
    }
    None
}
"}

{"path":"/workspace/native/src/runner.rs","command":"create","file_text":"use crate::args::Options;
use crate::colors;
use crate::files;
use crate::ignore::Ignores;
use crate::paths;
use serde_json::Value;
use std::collections::BTreeMap;
use std::fs;
use std::io::{self, BufRead, BufReader, Write};
use std::path::Path;
use std::process::{Command, Stdio};
use std::sync::mpsc;
use std::thread;
use std::time::Instant;
use tempfile::Builder as TmpBuilder;

const CHUNK_SIZE: usize = 50;

#[derive(Default, Clone)]
struct FileStats {
    error: u64,
    ok: u64,
    nochange: u64,
    skip: u64,
}

pub fn run(mut options: Options, paths: Vec<String>) -> io::Result<()> {
    let available_cpus = available_cpus();
    let cpus = match options.cpus {
        Some(n) if n.is_finite() && n > 0.0 => (n as usize).min(available_cpus).max(1),
        _ => available_cpus,
    };

    let extensions: Option<Vec<String>> = if options.extensions.is_empty() {
        None
    } else {
        Some(
            options
                .extensions
                .split(',')
                .map(|ext| format!(".{ext}"))
                .collect(),
        )
    };

    let mut ignores = Ignores::new();
    ignores.add(options.ignore_pattern.iter());
    if let Err(e) = ignores.add_from_files(&options.ignore_config) {
        return Err(e);
    }
    if options.gitignore {
        let git_ignore = std::env::current_dir()
            .unwrap_or_else(|_| Path::new(".").to_path_buf())
            .join(".gitignore");
        // Original calls addFromFile which statSync's and throws if missing.
        if let Err(e) = ignores.add_from_file(&git_ignore) {
            return Err(e);
        }
    }

    let transform_file = paths::resolve_transform(&options.transform);
    options.transform = transform_file.clone();

    if transform_file.starts_with("http://") || transform_file.starts_with("https://") {
        let local = download_transform(&transform_file)?;
        return transform(&local, paths, &options, cpus, extensions.as_deref(), &ignores);
    }

    if !Path::new(&transform_file).exists() {
        let msg = format!(
            "{} Transform file {} does not exist \n",
            colors::error_tag(),
            transform_file
        );
        let _ = io::stderr().write_all(msg.as_bytes());
        return Ok(());
    }

    transform(
        &transform_file,
        paths,
        &options,
        cpus,
        extensions.as_deref(),
        &ignores,
    )
}

fn available_cpus() -> usize {
    std::thread::available_parallelism()
        .map(|n| n.get().saturating_sub(1).max(1))
        .unwrap_or(1)
}

fn download_transform(url: &str) -> io::Result<String> {
    let resp = ureq::get(url).call().map_err(|e| {
        io::Error::new(io::ErrorKind::Other, format!("{e}"))
    })?;
    let mut contents = String::new();
    resp.into_reader().read_to_string(&mut contents)?;
    let ext = Path::new(url)
        .extension()
        .and_then(|s| s.to_str())
        .map(|s| format!(".{s}"))
        .unwrap_or_default();
    let tmp = TmpBuilder::new()
        .prefix("jscodeshift")
        .suffix(&ext)
        .tempfile()?;
    fs::write(tmp.path(), contents)?;
    let path = tmp.path().to_string_lossy().to_string();
    // Keep the file until process exit.
    std::mem::forget(tmp);
    Ok(path)
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{s}\n")
    }
}

fn show_file_stats(stats: &FileStats) {
    let mut out = String::from("Results: \n");
    out.push_str(&colors::red(&format!("{} errors\n", stats.error)));
    out.push_str(&colors::yellow(&format!("{} unmodified\n", stats.nochange)));
    out.push_str(&colors::yellow(&format!("{} skipped\n", stats.skip)));
    out.push_str(&colors::green(&format!("{} ok\n", stats.ok)));
    let _ = io::stdout().write_all(out.as_bytes());
}

fn show_stats(stats: &BTreeMap<String, f64>) {
    if stats.is_empty() {
        return;
    }
    let _ = io::stdout().write_all(colors::blue("Stats: \n").as_bytes());
    for (name, qty) in stats {
        let line = format!("{name}: {qty}\n");
        let _ = io::stdout().write_all(line.as_bytes());
    }
}

fn transform(
    transform_file: &str,
    paths: Vec<String>,
    options: &Options,
    cpus: usize,
    extensions: Option<&[String]>,
    ignores: &Ignores,
) -> io::Result<()> {
    let start = Instant::now();
    let files = files::get_all_files(&paths, extensions, ignores)?;
    let num_files = files.len();

    if num_files == 0 {
        let _ = io::stdout().write_all(b"No files selected, nothing to do. \n");
        return Ok(());
    }

    let processes = if options.run_in_band {
        1
    } else {
        num_files.min(cpus).max(1)
    };
    let chunk_size = if processes > 1 {
        ((num_files + processes - 1) / processes).min(CHUNK_SIZE)
    } else {
        num_files
    };

    if !options.silent {
        let _ = io::stdout().write_all(format!("Processing {num_files} files... \n").as_bytes());
        if !options.run_in_band {
            let _ = io::stdout().write_all(format!("Spawning {processes} workers...\n").as_bytes());
        }
        if options.dry {
            let msg = colors::green("Running in dry mode, no files will be written! \n");
            let _ = io::stdout().write_all(msg.as_bytes());
        }
    }

    let babel_arg = if options.babel { "babel" } else { "no-babel" };
    let host = paths::transform_host();
    let node = paths::node_binary();
    let options_json = options.to_worker_json();

    let (tx, rx) = mpsc::channel::<WorkerEvent>();

    struct WorkState {
        next_index: usize,
    }
    let mut work = WorkState { next_index: 0 };

    let mut next_chunk = |silent: bool, run_in_band: bool| -> Vec<String> {
        if !silent && !run_in_band && work.next_index < num_files {
            let n = chunk_size.min(num_files - work.next_index);
            let _ = io::stdout().write_all(format!("Sending {n} files to free worker...\n").as_bytes());
        }
        let end = (work.next_index + chunk_size).min(num_files);
        let chunk = files[work.next_index..end].to_vec();
        work.next_index = end;
        chunk
    };

    let mut children = Vec::new();
    for _ in 0..processes {
        let mut child = Command::new(&node)
            .arg(&host)
            .arg(transform_file)
            .arg(babel_arg)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .env("JSCODESHIFT_ROOT", paths::package_root())
            .spawn()?;

        let stdout = child.stdout.take().expect("stdout");
        let txc = tx.clone();
        thread::spawn(move || {
            let reader = BufReader::new(stdout);
            for line in reader.lines() {
                match line {
                    Ok(l) if !l.is_empty() => {
                        if let Ok(v) = serde_json::from_str::<Value>(&l) {
                            let _ = txc.send(WorkerEvent::Message(v));
                        }
                    }
                    Ok(_) => {}
                    Err(_) => break,
                }
            }
            let _ = txc.send(WorkerEvent::Disconnect);
        });

        let stdin = child.stdin.take().expect("stdin");
        children.push((child, stdin));
    }

    // Send initial work
    for i in 0..processes {
        let chunk = next_chunk(options.silent, options.run_in_band);
        send_work(&mut children[i].1, &chunk, &options_json)?;
    }

    let mut file_stats = FileStats::default();
    let mut stats_counter: BTreeMap<String, f64> = BTreeMap::new();
    let mut disconnected = 0usize;

    drop(tx);
    while let Ok(ev) = rx.recv() {
        match ev {
            WorkerEvent::Disconnect => {
                disconnected += 1;
                if disconnected >= processes {
                    break;
                }
            }
            WorkerEvent::Message(msg) => {
                let action = msg.get("action").and_then(|a| a.as_str()).unwrap_or("");
                match action {
                    "status" => {
                        let status = msg.get("status").and_then(|s| s.as_str()).unwrap_or("");
                        let m = msg.get("msg").and_then(|s| s.as_str()).unwrap_or("");
                        match status {
                            "error" => file_stats.error += 1,
                            "ok" => file_stats.ok += 1,
                            "nochange" => file_stats.nochange += 1,
                            "skip" => file_stats.skip += 1,
                            _ => {}
                        }
                        log_status(status, m, options.verbose);
                    }
                    "update" => {
                        let name = msg
                            .get("name")
                            .and_then(|s| s.as_str())
                            .unwrap_or("")
                            .to_string();
                        let qty = msg.get("quantity").and_then(|q| q.as_f64()).unwrap_or(1.0);
                        *stats_counter.entry(name).or_insert(0.0) += qty;
                    }
                    "free" => {
                        // Identify which worker? We broadcast next work via any free.
                        // The JS runner sends next() to the child that emitted free.
                        // We don't know which child; assign to first worker that we can.
                        // To preserve mapping, include worker index in protocol.
                        if let Some(idx) = msg.get("worker").and_then(|w| w.as_u64()) {
                            let chunk = next_chunk(options.silent, options.run_in_band);
                            if let Some((_, stdin)) = children.get_mut(idx as usize) {
                                let _ = send_work(stdin, &chunk, &options_json);
                            }
                        } else {
                            // Fallback: send to first still-open stdin
                            let chunk = next_chunk(options.silent, options.run_in_band);
                            for (_, stdin) in children.iter_mut() {
                                if send_work(stdin, &chunk, &options_json).is_ok() {
                                    break;
                                }
                            }
                        }
                    }
                    "report" => {
                        let file = msg.get("file").and_then(|s| s.as_str()).unwrap_or("");
                        let rmsg = msg.get("msg").and_then(|s| s.as_str()).unwrap_or("");
                        let line = line_break(&format!("{}{file} {rmsg}", colors::rep()));
                        let _ = io::stdout().write_all(line.as_bytes());
                    }
                    _ => {}
                }
            }
        }
    }

    for (mut child, stdin) in children {
        drop(stdin);
        let _ = child.wait();
    }

    let elapsed = start.elapsed();
    let time_elapsed = format!("{:.3}", elapsed.as_secs_f64());
    if !options.silent {
        let _ = io::stdout().write_all(b"All done. \n");
        show_file_stats(&file_stats);
        show_stats(&stats_counter);
        let _ = io::stdout().write_all(format!("Time elapsed: {time_elapsed}seconds \n").as_bytes());
        if options.fail_on_error && file_stats.error > 0 {
            std::process::exit(1);
        }
    }
    Ok(())
}

enum WorkerEvent {
    Message(Value),
    Disconnect,
}

fn send_work(stdin: &mut impl Write, files: &[String], options: &Value) -> io::Result<()> {
    let payload = serde_json::json!({
        "files": files,
        "options": options,
    });
    writeln!(stdin, "{payload}")?;
    stdin.flush()
}

fn log_status(status: &str, msg: &str, verbose: i32) {
    let text = line_break(msg);
    match status {
        "ok" if verbose >= 2 => {
            let _ = io::stdout().write_all(format!("{}{text}", colors::okk()).as_bytes());
        }
        "nochange" if verbose >= 1 => {
            let _ = io::stdout().write_all(format!("{}{text}", colors::noc()).as_bytes());
        }
        "skip" if verbose >= 1 => {
            let _ = io::stdout().write_all(format!("{}{text}", colors::skip()).as_bytes());
        }
        "error" if verbose >= 0 => {
            let _ = io::stdout().write_all(format!("{}{text}", colors::err()).as_bytes());
        }
        _ => {}
    }
}
"}

{"path":"/workspace/bridge/transform-host.js","command":"create","file_text":"/**
 * Minimal compatibility bridge that loads and executes JavaScript transforms.
 * Protocol: parent writes JSON work items to stdin (one per line).
 * This process writes JSON control messages to fd 3 (one per line).
 * stdout/stderr are inherited so --print and transform logging stay intact.
 */

'use strict';

const fs = require('fs');
const path = require('path');
const async = require('neo-async');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');

const packageRoot = process.env.JSCODESHIFT_ROOT
  ? process.env.JSCODESHIFT_ROOT
  : path.resolve(__dirname, '..');

const getParser = require(path.join(packageRoot, 'src', 'getParser'));
const jscodeshift = require(path.join(packageRoot, 'src', 'core'));

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

const workerIndex = Number(process.argv[4] || 0);
let transform;
let parserFromTransform;

function notify(data) {
  fs.writeSync(3, JSON.stringify(data) + '\n');
}

function finish() {
  try {
    if (process.stdin && typeof process.stdin.pause === 'function') {
      process.stdin.pause();
    }
  } catch (_) {}
  process.exit(0);
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform ||
    getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([
        presetEnv.default,
        {targets: {node: true}},
      ]);
    }
    presets.push(
      /\.tsx?$/.test(tr) ?
        require('@babel/preset-typescript').default :
        require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const module = require(tr);
  transform = typeof module.default === 'function' ?
    module.default :
    module;
  if (module.parser) {
    parserFromTransform = typeof module.parser === 'string' ?
      getParser(module.parser) :
      module.parser;
  }
}

function free() {
  notify({action: 'free', worker: workerIndex});
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  notify({action: 'status', status: status, msg: msg});
}

function report(file, msg) {
  notify({action: 'report', file, msg});
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  notify({action: 'update', name: name, quantity: quantity});
}

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  const lines = trace.split('\n');
  const result = [];
  lines.every(function(line) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function run(data) {
  const files = data.files;
  const options = data.options || {};
  if (!files.length) {
    finish();
    return;
  }
  async.each(
    files,
    function(file, callback) {
      fs.readFile(file, async function(err, source) {
        if (err) {
          updateStatus('error', file, 'File error: ' + err);
          callback();
          return;
        }
        source = source.toString();
        try {
          const jscodeshiftApi = prepareJscodeshift(options);
          const out = await transform(
            {
              path: file,
              source: source,
            },
            {
              j: jscodeshiftApi,
              jscodeshift: jscodeshiftApi,
              stats: options.dry ? stats : empty,
              report: msg => report(file, msg),
            },
            options
          );
          if (!out || out === source) {
            updateStatus(out ? 'nochange' : 'skip', file);
            callback();
            return;
          }
          if (options.print) {
            console.log(out); // eslint-disable-line no-console
          }
          if (!options.dry) {
            writeFileAtomic(file, out, function(err) {
              if (err) {
                updateStatus('error', file, 'File writer error: ' + err);
              } else {
                updateStatus('ok', file);
              }
              callback();
            });
          } else {
            updateStatus('ok', file);
            callback();
          }
        } catch(err) {
          updateStatus(
            'error',
            file,
            'Transformation error ('+ err.message.replace(/\n/g, ' ') + ')\n' + trimStackTrace(err.stack)
          );
          callback();
        }
      });
    },
    function(err) {
      if (err) {
        updateStatus('error', '', 'This should never be shown!');
      }
      free();
    }
  );
}

setup(process.argv[2], process.argv[3]);

const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  crlfDelay: Infinity,
});
rl.on('line', (line) => {
  if (!line) {
    return;
  }
  let data;
  try {
    data = JSON.parse(line);
  } catch (_) {
    return;
  }
  run(data);
});
"}

