 * LICENSE file in the root directory of this source tree.
 */

'use strict';

const { spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const candidates = [
  path.join(__dirname, 'jscodeshift'),
  path.join(root, 'target', 'release', 'jscodeshift'),
  path.join(root, 'target', 'debug', 'jscodeshift'),
];

const bin = candidates.find((candidate) => {
  try {
    fs.accessSync(candidate, fs.constants.X_OK);
    return true;
  } catch (_) {
    return false;
  }
});

if (!bin) {
  process.stderr.write(
    'jscodeshift native binary not found. Run the build command first.\n'
  );
  process.exit(1);
}

const result = spawnSync(bin, process.argv.slice(2), {
  stdio: 'inherit',
  env: Object.assign({}, process.env, {
    JSCODESHIFT_ROOT: process.env.JSCODESHIFT_ROOT || root,
  }),
});

if (result.error) {
  process.stderr.write(String(result.error) + '\n');
  process.exit(1);
}

process.exit(result.status === null ? 1 : result.status);
"}

