{"path":"/workspace/native/src/runner.rs","command":"create","file_text":"use crate::args::Options;
use crate::colors;
use crate::files;
use crate::ignore::Ignores;
use crate::paths;
use serde_json::Value;
use std::collections::BTreeMap;
use std::fs;
use std::io::{self, BufRead, BufReader, Read, Write};
use std::os::unix::io::{AsRawFd, FromRawFd};
use std::path::Path;
use std::process::{Command, Stdio};
use std::sync::mpsc;
use std::thread;
use std::time::Instant;
use tempfile::Builder as TmpBuilder;

const CHUNK_SIZE: usize = 50;

#[derive(Default, Clone)]
struct FileStats {
    error: u64,
    ok: u64,
    nochange: u64,
    skip: u64,
}

pub fn run(mut options: Options, paths: Vec<String>) -> io::Result<()> {
    let available_cpus = available_cpus();
    let cpus = match options.cpus {
        Some(n) if n.is_finite() && n > 0.0 => (n as usize).min(available_cpus).max(1),
        _ => available_cpus,
    };

    let extensions: Option<Vec<String>> = if options.extensions.is_empty() {
        None
    } else {
        Some(
            options
                .extensions
                .split(',')
                .map(|ext| format!(".{ext}"))
                .collect(),
        )
    };

    let mut ignores = Ignores::new();
    ignores.add(options.ignore_pattern.iter());
    ignores.add_from_files(&options.ignore_config)?;
    if options.gitignore {
        let git_ignore = std::env::current_dir()
            .unwrap_or_else(|_| Path::new(".").to_path_buf())
            .join(".gitignore");
        ignores.add_from_file(&git_ignore)?;
    }

    let transform_file = paths::resolve_transform(&options.transform);
    options.transform = transform_file.clone();

    if transform_file.starts_with("http://") || transform_file.starts_with("https://") {
        let local = download_transform(&transform_file)?;
        return transform(&local, paths, &options, cpus, extensions.as_deref(), &ignores);
    }

    if !Path::new(&transform_file).exists() {
        let msg = format!(
            "{} Transform file {} does not exist \n",
            colors::error_tag(),
            transform_file
        );
        let _ = io::stderr().write_all(msg.as_bytes());
        return Ok(());
    }

    transform(
        &transform_file,
        paths,
        &options,
        cpus,
        extensions.as_deref(),
        &ignores,
    )
}

fn available_cpus() -> usize {
    std::thread::available_parallelism()
        .map(|n| n.get().saturating_sub(1).max(1))
        .unwrap_or(1)
}

fn download_transform(url: &str) -> io::Result<String> {
    let resp = ureq::get(url)
        .call()
        .map_err(|e| io::Error::new(io::ErrorKind::Other, format!("{e}")))?;
    let mut contents = String::new();
    resp.into_reader().read_to_string(&mut contents)?;
    let ext = Path::new(url)
        .extension()
        .and_then(|s| s.to_str())
        .map(|s| format!(".{s}"))
        .unwrap_or_default();
    let tmp = TmpBuilder::new()
        .prefix("jscodeshift")
        .suffix(&ext)
        .tempfile()?;
    fs::write(tmp.path(), contents)?;
    let path = tmp.path().to_string_lossy().to_string();
    std::mem::forget(tmp);
    Ok(path)
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{s}\n")
    }
}

fn show_file_stats(stats: &FileStats) {
    let mut out = String::from("Results: \n");
    out.push_str(&colors::red(&format!("{} errors\n", stats.error)));
    out.push_str(&colors::yellow(&format!("{} unmodified\n", stats.nochange)));
    out.push_str(&colors::yellow(&format!("{} skipped\n", stats.skip)));
    out.push_str(&colors::green(&format!("{} ok\n", stats.ok)));
    let _ = io::stdout().write_all(out.as_bytes());
}

fn show_stats(stats: &BTreeMap<String, f64>) {
    if stats.is_empty() {
        return;
    }
    let _ = io::stdout().write_all(colors::blue("Stats: \n").as_bytes());
    for (name, qty) in stats {
        // JS prints numbers via string concat; integers appear without decimals.
        let qty_s = if qty.fract() == 0.0 {
            format!("{}", *qty as i64)
        } else {
            format!("{qty}")
        };
        let line = format!("{name}: {qty_s}\n");
        let _ = io::stdout().write_all(line.as_bytes());
    }
}

fn transform(
    transform_file: &str,
    paths: Vec<String>,
    options: &Options,
    cpus: usize,
    extensions: Option<&[String]>,
    ignores: &Ignores,
) -> io::Result<()> {
    let start = Instant::now();
    let files = files::get_all_files(&paths, extensions, ignores)?;
    let num_files = files.len();

    if num_files == 0 {
        let _ = io::stdout().write_all(b"No files selected, nothing to do. \n");
        return Ok(());
    }

    let processes = if options.run_in_band {
        1
    } else {
        num_files.min(cpus).max(1)
    };
    let chunk_size = if processes > 1 {
        ((num_files + processes - 1) / processes).min(CHUNK_SIZE)
    } else {
        num_files
    };

    if !options.silent {
        let _ = io::stdout().write_all(format!("Processing {num_files} files... \n").as_bytes());
        if !options.run_in_band {
            let _ = io::stdout().write_all(format!("Spawning {processes} workers...\n").as_bytes());
        }
        if options.dry {
            let msg = colors::green("Running in dry mode, no files will be written! \n");
            let _ = io::stdout().write_all(msg.as_bytes());
        }
    }

    let babel_arg = if options.babel { "babel" } else { "no-babel" };
    let host = paths::transform_host();
    let node = paths::node_binary();
    let options_json = options.to_worker_json();
    let package_root = paths::package_root();

    let (tx, rx) = mpsc::channel::<WorkerEvent>();

    struct WorkState {
        next_index: usize,
    }
    let mut work = WorkState { next_index: 0 };

    let mut next_chunk = |silent: bool, run_in_band: bool| -> Vec<String> {
        if !silent && !run_in_band && work.next_index < num_files {
            let n = chunk_size.min(num_files - work.next_index);
            let _ =
                io::stdout().write_all(format!("Sending {n} files to free worker...\n").as_bytes());
        }
        let end = (work.next_index + chunk_size).min(num_files);
        let chunk = files[work.next_index..end].to_vec();
        work.next_index = end;
        chunk
    };

    let mut children = Vec::new();
    for idx in 0..processes {
        let (ctl_reader, ctl_writer) = os_pipe::pipe()?;
        let writer_fd = ctl_writer.as_raw_fd();

        let mut command = Command::new(&node);
        command
            .arg(&host)
            .arg(transform_file)
            .arg(babel_arg)
            .arg(idx.to_string())
            .stdin(Stdio::piped())
            .stdout(Stdio::inherit())
            .stderr(Stdio::inherit())
            .env("JSCODESHIFT_ROOT", &package_root);

        // Map the write end of the control pipe to fd 3 in the child.
        #[cfg(unix)]
        {
            use std::os::unix::io::IntoRawFd;
            use std::os::unix::process::CommandExt;
            let fd = ctl_writer.into_raw_fd();
            unsafe {
                command.pre_exec(move || {
                    if fd != 3 {
