{"path":"/workspace/native/src/out.rs","command":"create","file_text":"/// Write to stdout/stderr with a single unbuffered syscall sequence so ANSI
/// wrappers that contain a newline cannot be split across other writers.

pub fn stdout(bytes: &[u8]) {
    write_fd(1, bytes);
}

pub fn stderr(bytes: &[u8]) {
    write_fd(2, bytes);
}

#[cfg(unix)]
fn write_fd(fd: i32, bytes: &[u8]) {
    let mut written = 0usize;
    while written < bytes.len() {
        let n = unsafe {
            libc::write(
                fd,
                bytes[written..].as_ptr() as *const libc::c_void,
                bytes.len() - written,
            )
        };
        if n < 0 {
            return;
        }
        written += n as usize;
    }
}

#[cfg(not(unix))]
fn write_fd(_fd: i32, bytes: &[u8]) {
    use std::io::Write;
    if _fd == 2 {
        let _ = std::io::stderr().write_all(bytes);
        let _ = std::io::stderr().flush();
    } else {
        let _ = std::io::stdout().write_all(bytes);
        let _ = std::io::stdout().flush();
    }
}
"}

