{"path":"/workspace/native/src/ignore.rs","command":"str_replace","old_str":"fn set_matches(set: &GlobSet, path: &str) -> bool {
    // picomatch {dot:true} matches hidden files; globset does this by default
    // unless we set require_literal_separator. Also try basename match like picomatch.
    if set.is_match(path) {
        return true;
    }
    if let Some(name) = Path::new(path).file_name().and_then(|s| s.to_str()) {
        if set.is_match(name) {
            return true;
        }
    }
    false
}","new_str":"fn set_matches(set: &GlobSet, path: &str) -> bool {
    if set.is_match(path) {
        return true;
    }
    // picomatch also matches against the basename and against any
    // trailing path suffix (`a/b/c` is also tried as `b/c` and `c`).
    let mut rest = path;
    while let Some(idx) = rest.find(|c| c == '/' || c == '\\') {
        rest = &rest[idx + 1..];
        if rest.is_empty() {
            break;
        }
        if set.is_match(rest) {
            return true;
        }
    }
    false
}"}

